def area_tier(area_m2, minimum_m2=40.0, generous_m2=70.0):
    """Classify one room area into a three-tier evidence band."""
    if area_m2 >= generous_m2:
        return 'generous area'
    elif area_m2 >= minimum_m2:
        return 'meets area criterion'
    return 'review area'

